import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../tests/utils";
import { ConversationEventType, type Conversation, type EventMetadata } from "../types";
import { LangfuseSessionButton } from "./LangfuseSessionButton";

const makeConversation = (metadata: EventMetadata = { parseData: {} }): Conversation => ({
  id: "session-1",
  startDate: new Date().toISOString(),
  reviewed: false,
  totalNumberOfUserMessages: 1,
  events: [
    {
      __typename: "ConversationEvent",
      id: "event-1",
      conversationEventType: ConversationEventType.BotTurnEnded,
      name: "bot",
      actionText: "",
      flowId: "",
      slotValue: null,
      stepId: "",
      timestamp: new Date().toISOString(),
      originalTimestamp: 0,
      metadata,
    },
  ],
});

const withTraceUrl = makeConversation({
  parseData: {},
  langfuse_trace_url: "https://langfuse.test/project/p1/traces/t1",
});

describe("LangfuseSessionButton", () => {
  it("links to the derived session URL when an event carries a trace URL", () => {
    renderWithProviders(
      <LangfuseSessionButton conversationList={[withTraceUrl]} sessionId="session-1" />,
    );

    expect(screen.getByTestId("open-langfuse-session")).toHaveAttribute(
      "href",
      "https://langfuse.test/project/p1/sessions/session-1",
    );
  });

  it("renders a disabled button when no event carries Langfuse metadata", () => {
    renderWithProviders(
      <LangfuseSessionButton conversationList={[makeConversation()]} sessionId="session-1" />,
    );

    expect(screen.getByTestId("open-langfuse-session")).toBeDisabled();
  });

  it("renders nothing when langfuseEnabled is false", () => {
    renderWithProviders(
      <LangfuseSessionButton conversationList={[withTraceUrl]} sessionId="session-1" />,
      { initialStoreState: { langfuseEnabled: false } },
    );

    expect(screen.queryByTestId("open-langfuse-session")).not.toBeInTheDocument();
  });
});
